function relatedDocs(d){const rel=WEB_DOCS.filter(x=>x!==d&&x.keys.some(k=>d.keys.includes(k))).slice(0,4);return rel.map(x=>`<a data-nav="${x.url}">${x.title}<small>${x.source}</small></a>`).join('')}
